window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e9613b2fec326fcd"]={"versions": [{"id": "FIG-e9613b2fec326fcd", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM 2.0-Prozessdiagramm (Software & Systems Process Engineering Metamodel) der AUTOSAR Adaptive Platform (AP) Methodology.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der methodischen Entwurfsschritte zur Erstellung einer <code>SoftwareCluster</code>-Entwurfsbeschreibung (<code>SW Cluster Design Description</code>) für UCM-fähige (Update and Configuration Management) adaptive Steuergeräte. Es definiert die Aggregation von Prozess-Deployments, Zielmaschinen-Topologien und Diagnosekonfigurationen in ein unabhängig aktualisierbares Software-Bündel (Software Cluster).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Paket</p>\n<ul class=\"fig-list\">\n<li><strong><code>SW Cluster Design</code></strong> (<code>«SPEM_MethodContentPackage»</code>): Kapselt die methodischen Aufgaben und Artefakte zur Cluster-Assemblierung.</li>\n</ul>\n<p class=\"fig-p\">#### Prozessschritte / Aktivitäten (<code>«TaskDefinition»</code>)</p>\n<ol class=\"fig-list\">\n<li><strong><code>Define Process Design</code></strong> (außerhalb des Pakets): Transformiert die ausführbaren Artefakte in prozessspezifische Ausführungsbeschreibungen.</li>\n<li><strong><code>Associate content elements</code></strong>: Verknüpft Prozesse und Machine-Artefakte zu deployment-fähigen Clusterelementen.</li>\n<li><strong><code>Associate Diagnostic Address and Contribution</code></strong>: Weist dem Software-Cluster spezifische Diagnose-Identifikatoren (DoIP/UDS Logical Address, Target Address) sowie diagnosebezogene Anteile zu.</li>\n</ol>\n<p class=\"fig-p\">#### Artefakte & Arbeitsergebnisse</p>\n<ul class=\"fig-list\">\n<li><strong><code>«Artifact» Executable Description</code></strong>: Manifest-Beschreibung der ausführbaren Binärdateien (<code>Executable</code>, <code>StartupConfigSet</code>).</li>\n<li><strong><code>«Deliverable» Process Design Description</code></strong>: Prozessdefinitionen (<code>Process</code>, <code>ProcessDesign</code>, Ressourcenzuordnungen, Mode-Management-Abhängigkeiten).</li>\n<li><strong><code>«Deliverable» Machine Design</code></strong>: Abstrakte Maschinen- und Hardwarekonfiguration (<code>MachineDesign</code>, Netzwerkschnittstellen, Prozessorkerne, Speicherarchitektur).</li>\n<li><strong><code>«Deliverable» Diagnostic Design</code></strong>: Diagnoseentwurf (<code>DiagnosticContributionSet</code>, Service-Tabellen, DEXT/UDS-Konfiguration).</li>\n<li><strong><code>«Artifact» Associated uploadable elements</code></strong>: Konkrete Payload- und Artefaktliste des Clusters (Binaries, Konfigurationsdateien, Kalibrierdaten).</li>\n<li><strong><code>«Deliverable» SW Cluster Design Description</code></strong>: Vollständiges ARXML-Manifest des Software-Clusters (<code>SoftwareCluster</code>), das als Eingabe für UCM und nachgelagerte Packaging-Schritte dient.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«input»</code></strong>:</li>\n<li><code>Executable Description</code> $\\rightarrow$ <code>Define Process Design</code></li>\n<li><code>Process Design Description</code> $\\rightarrow$ <code>Associate content elements</code></li>\n<li><code>Machine Design</code> $\\rightarrow$ <code>Associate content elements</code></li>\n<li><code>Diagnostic Design</code> $\\rightarrow$ <code>Associate Diagnostic Address and Contribution</code></li>\n<li><strong><code>«output»</code></strong>:</li>\n<li><code>Define Process Design</code> $\\rightarrow$ <code>Process Design Description</code></li>\n<li><code>Associate Diagnostic Address and Contribution</code> $\\rightarrow$ <code>SW Cluster Design Description</code></li>\n<li><code>Associate content elements</code> $\\rightarrow$ <code>Associated uploadable elements</code></li>\n<li><strong><code>«contributes»</code></strong>:</li>\n<li><code>Associated uploadable elements</code> $\\rightarrow$ <code>SW Cluster Design Description</code> (struktureller/inhaltlicher Beitrag zur Gesamt-Clusterdefinition).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der methodische Entwurf folgt einer deterministischen Abhängigkeitsreihenfolge:</p>\n<ol class=\"fig-list\">\n<li><strong>Prozessgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Input:</strong> Bereitstellung der <code>Executable Description</code> (enthält Einstiegspunkte, Abhängigkeiten und Startparameter).</li>\n<li><strong>Task:</strong> <code>Define Process Design</code> instanziiert Prozesse, definiert Prozesszustände und Ausführungsmodi.</li>\n<li><strong>Output:</strong> <code>Process Design Description</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inhaltsassoziation (paralleler/nachgelagerter Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Input:</strong> Zusammenführung von <code>Process Design Description</code> und <code>Machine Design</code> (Bindung an Hardware-Ressourcen der Zielplattform).</li>\n<li><strong>Task:</strong> <code>Associate content elements</code> bildet ab, welche Prozesse und Begleitdateien zusammen als UCM-Container deployt werden.</li>\n<li><strong>Output:</strong> <code>Associated uploadable elements</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Diagnose- und Metadaten-Synthese:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Task:</strong> <code>Associate Diagnostic Address and Contribution</code> konsumiert <code>Diagnostic Design</code> und erzeugt die Basis des <code>SW Cluster Design Description</code>.</li>\n<li><strong>Konsolidierung:</strong> Über die <code>«contributes»</code>-Kante fließen die <code>Associated uploadable elements</code> in die <code>SW Cluster Design Description</code> ein.</li>\n<li><strong>Endzustand:</strong> Ein in sich geschlossenes Manifest (<code>SoftwareCluster</code>), das funktionale Prozesse, Maschinenbezug und Diagnoseadressierung vereint.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>UCM-Konformität (AUTOSAR AP Update and Configuration Management):</strong></li>\n</ul>\n<p class=\"fig-p\">Ein <code>SoftwareCluster</code> ist die atomare Einheit für Software-Updates (OTA/FOTA). Entwickler müssen sicherstellen, dass alle referenzierten Binärdateien (<code>Executable Description</code>) und deren OS-Prozessabbildungen (<code>Process Design Description</code>) konsistent im Cluster gekapselt sind.</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns:</strong></li>\n</ul>\n<p class=\"fig-p\">Das <code>Machine Design</code> entkoppelt die physische ECU-Hardware von der Applikationslogik. Die Zuordnung im Task <code>Associate content elements</code> darf keine harten Hardwarespezifika in die Anwendungsarchitektur leaken; die Bindung erfolgt erst auf Clusterebene.</p>\n<ul class=\"fig-list\">\n<li><strong>Diagnose-Adressierung (DoIP / Diagnostic Management):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Entkopplung via <code>Associate Diagnostic Address and Contribution</code> ist zwingend erforderlich, da jeder Software Cluster eine eigenständige Diagnoseadresse für cluster-individuelle Software-Identifikation (<code>DID F180</code>/<code>F188</code> etc.) und Aktualisierungsroutinen über UCM benötigt.</p>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Austauschformate:</strong></li>\n<li>Eingangsdateien: ARXML-Exzerpte für <code>Executable</code>, <code>MachineDesign</code> und <code>DiagnosticExtract</code>.</li>\n<li>Ergebnisdatei: Das <code>SoftwareCluster</code>-ARXML, welches die Elementtypen <code>ProcessToMachineMappingDesign</code>, <code>SoftwareClusterToMachineDesignMapping</code> und UCM-Package-Informationen für den Generierungsprozess der Zielplattform bereitstellt.</li>\n</ul>"}, {"id": "FIG-fef9d7879eec3246", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM 2.0-Prozessdiagramm (Software & Systems Process Engineering Metamodel) der AUTOSAR Adaptive Platform (AP) Methodology.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der methodischen Entwurfsschritte zur Erstellung einer <code>SoftwareCluster</code>-Entwurfsbeschreibung (<code>SW Cluster Design Description</code>) für UCM-fähige (Update and Configuration Management) adaptive Steuergeräte. Es definiert die Aggregation von Prozess-Deployments, Zielmaschinen-Topologien und Diagnosekonfigurationen in ein unabhängig aktualisierbares Software-Bündel (Software Cluster).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Paket</p>\n<ul class=\"fig-list\">\n<li><strong><code>SW Cluster Design</code></strong> (<code>«SPEM_MethodContentPackage»</code>): Kapselt die methodischen Aufgaben und Artefakte zur Cluster-Assemblierung.</li>\n</ul>\n<p class=\"fig-p\">#### Prozessschritte / Aktivitäten (<code>«TaskDefinition»</code>)</p>\n<ol class=\"fig-list\">\n<li><strong><code>Define Process Design</code></strong> (außerhalb des Pakets): Transformiert die ausführbaren Artefakte in prozessspezifische Ausführungsbeschreibungen.</li>\n<li><strong><code>Associate content elements</code></strong>: Verknüpft Prozesse und Machine-Artefakte zu deployment-fähigen Clusterelementen.</li>\n<li><strong><code>Associate Diagnostic Address and Contribution</code></strong>: Weist dem Software-Cluster spezifische Diagnose-Identifikatoren (DoIP/UDS Logical Address, Target Address) sowie diagnosebezogene Anteile zu.</li>\n</ol>\n<p class=\"fig-p\">#### Artefakte & Arbeitsergebnisse</p>\n<ul class=\"fig-list\">\n<li><strong><code>«Artifact» Executable Description</code></strong>: Manifest-Beschreibung der ausführbaren Binärdateien (<code>Executable</code>, <code>StartupConfigSet</code>).</li>\n<li><strong><code>«Deliverable» Process Design Description</code></strong>: Prozessdefinitionen (<code>Process</code>, <code>ProcessDesign</code>, Ressourcenzuordnungen, Mode-Management-Abhängigkeiten).</li>\n<li><strong><code>«Deliverable» Machine Design</code></strong>: Abstrakte Maschinen- und Hardwarekonfiguration (<code>MachineDesign</code>, Netzwerkschnittstellen, Prozessorkerne, Speicherarchitektur).</li>\n<li><strong><code>«Deliverable» Diagnostic Design</code></strong>: Diagnoseentwurf (<code>DiagnosticContributionSet</code>, Service-Tabellen, DEXT/UDS-Konfiguration).</li>\n<li><strong><code>«Artifact» Associated uploadable elements</code></strong>: Konkrete Payload- und Artefaktliste des Clusters (Binaries, Konfigurationsdateien, Kalibrierdaten).</li>\n<li><strong><code>«Deliverable» SW Cluster Design Description</code></strong>: Vollständiges ARXML-Manifest des Software-Clusters (<code>SoftwareCluster</code>), das als Eingabe für UCM und nachgelagerte Packaging-Schritte dient.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«input»</code></strong>:</li>\n<li><code>Executable Description</code> $\\rightarrow$ <code>Define Process Design</code></li>\n<li><code>Process Design Description</code> $\\rightarrow$ <code>Associate content elements</code></li>\n<li><code>Machine Design</code> $\\rightarrow$ <code>Associate content elements</code></li>\n<li><code>Diagnostic Design</code> $\\rightarrow$ <code>Associate Diagnostic Address and Contribution</code></li>\n<li><strong><code>«output»</code></strong>:</li>\n<li><code>Define Process Design</code> $\\rightarrow$ <code>Process Design Description</code></li>\n<li><code>Associate Diagnostic Address and Contribution</code> $\\rightarrow$ <code>SW Cluster Design Description</code></li>\n<li><code>Associate content elements</code> $\\rightarrow$ <code>Associated uploadable elements</code></li>\n<li><strong><code>«contributes»</code></strong>:</li>\n<li><code>Associated uploadable elements</code> $\\rightarrow$ <code>SW Cluster Design Description</code> (struktureller/inhaltlicher Beitrag zur Gesamt-Clusterdefinition).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der methodische Entwurf folgt einer deterministischen Abhängigkeitsreihenfolge:</p>\n<ol class=\"fig-list\">\n<li><strong>Prozessgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Input:</strong> Bereitstellung der <code>Executable Description</code> (enthält Einstiegspunkte, Abhängigkeiten und Startparameter).</li>\n<li><strong>Task:</strong> <code>Define Process Design</code> instanziiert Prozesse, definiert Prozesszustände und Ausführungsmodi.</li>\n<li><strong>Output:</strong> <code>Process Design Description</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inhaltsassoziation (paralleler/nachgelagerter Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Input:</strong> Zusammenführung von <code>Process Design Description</code> und <code>Machine Design</code> (Bindung an Hardware-Ressourcen der Zielplattform).</li>\n<li><strong>Task:</strong> <code>Associate content elements</code> bildet ab, welche Prozesse und Begleitdateien zusammen als UCM-Container deployt werden.</li>\n<li><strong>Output:</strong> <code>Associated uploadable elements</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Diagnose- und Metadaten-Synthese:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Task:</strong> <code>Associate Diagnostic Address and Contribution</code> konsumiert <code>Diagnostic Design</code> und erzeugt die Basis des <code>SW Cluster Design Description</code>.</li>\n<li><strong>Konsolidierung:</strong> Über die <code>«contributes»</code>-Kante fließen die <code>Associated uploadable elements</code> in die <code>SW Cluster Design Description</code> ein.</li>\n<li><strong>Endzustand:</strong> Ein in sich geschlossenes Manifest (<code>SoftwareCluster</code>), das funktionale Prozesse, Maschinenbezug und Diagnoseadressierung vereint.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>UCM-Konformität (AUTOSAR AP Update and Configuration Management):</strong></li>\n</ul>\n<p class=\"fig-p\">Ein <code>SoftwareCluster</code> ist die atomare Einheit für Software-Updates (OTA/FOTA). Entwickler müssen sicherstellen, dass alle referenzierten Binärdateien (<code>Executable Description</code>) und deren OS-Prozessabbildungen (<code>Process Design Description</code>) konsistent im Cluster gekapselt sind.</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns:</strong></li>\n</ul>\n<p class=\"fig-p\">Das <code>Machine Design</code> entkoppelt die physische ECU-Hardware von der Applikationslogik. Die Zuordnung im Task <code>Associate content elements</code> darf keine harten Hardwarespezifika in die Anwendungsarchitektur leaken; die Bindung erfolgt erst auf Clusterebene.</p>\n<ul class=\"fig-list\">\n<li><strong>Diagnose-Adressierung (DoIP / Diagnostic Management):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Entkopplung via <code>Associate Diagnostic Address and Contribution</code> ist zwingend erforderlich, da jeder Software Cluster eine eigenständige Diagnoseadresse für cluster-individuelle Software-Identifikation (<code>DID F180</code>/<code>F188</code> etc.) und Aktualisierungsroutinen über UCM benötigt.</p>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Austauschformate:</strong></li>\n<li>Eingangsdateien: ARXML-Exzerpte für <code>Executable</code>, <code>MachineDesign</code> und <code>DiagnosticExtract</code>.</li>\n<li>Ergebnisdatei: Das <code>SoftwareCluster</code>-ARXML, welches die Elementtypen <code>ProcessToMachineMappingDesign</code>, <code>SoftwareClusterToMachineDesignMapping</code> und UCM-Package-Informationen für den Generierungsprozess der Zielplattform bereitstellt.</li>\n</ul>"}, {"id": "FIG-6a57c386160b5ead", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM 2.0-Prozessdiagramm (Software & Systems Process Engineering Metamodel) der AUTOSAR Adaptive Platform (AP) Methodology.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der methodischen Entwurfsschritte zur Erstellung einer <code>SoftwareCluster</code>-Entwurfsbeschreibung (<code>SW Cluster Design Description</code>) für UCM-fähige (Update and Configuration Management) adaptive Steuergeräte. Es definiert die Aggregation von Prozess-Deployments, Zielmaschinen-Topologien und Diagnosekonfigurationen in ein unabhängig aktualisierbares Software-Bündel (Software Cluster).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Paket</p>\n<ul class=\"fig-list\">\n<li><strong><code>SW Cluster Design</code></strong> (<code>«SPEM_MethodContentPackage»</code>): Kapselt die methodischen Aufgaben und Artefakte zur Cluster-Assemblierung.</li>\n</ul>\n<p class=\"fig-p\">#### Prozessschritte / Aktivitäten (<code>«TaskDefinition»</code>)</p>\n<ol class=\"fig-list\">\n<li><strong><code>Define Process Design</code></strong> (außerhalb des Pakets): Transformiert die ausführbaren Artefakte in prozessspezifische Ausführungsbeschreibungen.</li>\n<li><strong><code>Associate content elements</code></strong>: Verknüpft Prozesse und Machine-Artefakte zu deployment-fähigen Clusterelementen.</li>\n<li><strong><code>Associate Diagnostic Address and Contribution</code></strong>: Weist dem Software-Cluster spezifische Diagnose-Identifikatoren (DoIP/UDS Logical Address, Target Address) sowie diagnosebezogene Anteile zu.</li>\n</ol>\n<p class=\"fig-p\">#### Artefakte & Arbeitsergebnisse</p>\n<ul class=\"fig-list\">\n<li><strong><code>«Artifact» Executable Description</code></strong>: Manifest-Beschreibung der ausführbaren Binärdateien (<code>Executable</code>, <code>StartupConfigSet</code>).</li>\n<li><strong><code>«Deliverable» Process Design Description</code></strong>: Prozessdefinitionen (<code>Process</code>, <code>ProcessDesign</code>, Ressourcenzuordnungen, Mode-Management-Abhängigkeiten).</li>\n<li><strong><code>«Deliverable» Machine Design</code></strong>: Abstrakte Maschinen- und Hardwarekonfiguration (<code>MachineDesign</code>, Netzwerkschnittstellen, Prozessorkerne, Speicherarchitektur).</li>\n<li><strong><code>«Deliverable» Diagnostic Design</code></strong>: Diagnoseentwurf (<code>DiagnosticContributionSet</code>, Service-Tabellen, DEXT/UDS-Konfiguration).</li>\n<li><strong><code>«Artifact» Associated uploadable elements</code></strong>: Konkrete Payload- und Artefaktliste des Clusters (Binaries, Konfigurationsdateien, Kalibrierdaten).</li>\n<li><strong><code>«Deliverable» SW Cluster Design Description</code></strong>: Vollständiges ARXML-Manifest des Software-Clusters (<code>SoftwareCluster</code>), das als Eingabe für UCM und nachgelagerte Packaging-Schritte dient.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«input»</code></strong>:</li>\n<li><code>Executable Description</code> $\\rightarrow$ <code>Define Process Design</code></li>\n<li><code>Process Design Description</code> $\\rightarrow$ <code>Associate content elements</code></li>\n<li><code>Machine Design</code> $\\rightarrow$ <code>Associate content elements</code></li>\n<li><code>Diagnostic Design</code> $\\rightarrow$ <code>Associate Diagnostic Address and Contribution</code></li>\n<li><strong><code>«output»</code></strong>:</li>\n<li><code>Define Process Design</code> $\\rightarrow$ <code>Process Design Description</code></li>\n<li><code>Associate Diagnostic Address and Contribution</code> $\\rightarrow$ <code>SW Cluster Design Description</code></li>\n<li><code>Associate content elements</code> $\\rightarrow$ <code>Associated uploadable elements</code></li>\n<li><strong><code>«contributes»</code></strong>:</li>\n<li><code>Associated uploadable elements</code> $\\rightarrow$ <code>SW Cluster Design Description</code> (struktureller/inhaltlicher Beitrag zur Gesamt-Clusterdefinition).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der methodische Entwurf folgt einer deterministischen Abhängigkeitsreihenfolge:</p>\n<ol class=\"fig-list\">\n<li><strong>Prozessgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Input:</strong> Bereitstellung der <code>Executable Description</code> (enthält Einstiegspunkte, Abhängigkeiten und Startparameter).</li>\n<li><strong>Task:</strong> <code>Define Process Design</code> instanziiert Prozesse, definiert Prozesszustände und Ausführungsmodi.</li>\n<li><strong>Output:</strong> <code>Process Design Description</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inhaltsassoziation (paralleler/nachgelagerter Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Input:</strong> Zusammenführung von <code>Process Design Description</code> und <code>Machine Design</code> (Bindung an Hardware-Ressourcen der Zielplattform).</li>\n<li><strong>Task:</strong> <code>Associate content elements</code> bildet ab, welche Prozesse und Begleitdateien zusammen als UCM-Container deployt werden.</li>\n<li><strong>Output:</strong> <code>Associated uploadable elements</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Diagnose- und Metadaten-Synthese:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Task:</strong> <code>Associate Diagnostic Address and Contribution</code> konsumiert <code>Diagnostic Design</code> und erzeugt die Basis des <code>SW Cluster Design Description</code>.</li>\n<li><strong>Konsolidierung:</strong> Über die <code>«contributes»</code>-Kante fließen die <code>Associated uploadable elements</code> in die <code>SW Cluster Design Description</code> ein.</li>\n<li><strong>Endzustand:</strong> Ein in sich geschlossenes Manifest (<code>SoftwareCluster</code>), das funktionale Prozesse, Maschinenbezug und Diagnoseadressierung vereint.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>UCM-Konformität (AUTOSAR AP Update and Configuration Management):</strong></li>\n</ul>\n<p class=\"fig-p\">Ein <code>SoftwareCluster</code> ist die atomare Einheit für Software-Updates (OTA/FOTA). Entwickler müssen sicherstellen, dass alle referenzierten Binärdateien (<code>Executable Description</code>) und deren OS-Prozessabbildungen (<code>Process Design Description</code>) konsistent im Cluster gekapselt sind.</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns:</strong></li>\n</ul>\n<p class=\"fig-p\">Das <code>Machine Design</code> entkoppelt die physische ECU-Hardware von der Applikationslogik. Die Zuordnung im Task <code>Associate content elements</code> darf keine harten Hardwarespezifika in die Anwendungsarchitektur leaken; die Bindung erfolgt erst auf Clusterebene.</p>\n<ul class=\"fig-list\">\n<li><strong>Diagnose-Adressierung (DoIP / Diagnostic Management):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Entkopplung via <code>Associate Diagnostic Address and Contribution</code> ist zwingend erforderlich, da jeder Software Cluster eine eigenständige Diagnoseadresse für cluster-individuelle Software-Identifikation (<code>DID F180</code>/<code>F188</code> etc.) und Aktualisierungsroutinen über UCM benötigt.</p>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Austauschformate:</strong></li>\n<li>Eingangsdateien: ARXML-Exzerpte für <code>Executable</code>, <code>MachineDesign</code> und <code>DiagnosticExtract</code>.</li>\n<li>Ergebnisdatei: Das <code>SoftwareCluster</code>-ARXML, welches die Elementtypen <code>ProcessToMachineMappingDesign</code>, <code>SoftwareClusterToMachineDesignMapping</code> und UCM-Package-Informationen für den Generierungsprozess der Zielplattform bereitstellt.</li>\n</ul>"}], "trans": [{"from": "FIG-e9613b2fec326fcd", "to": "FIG-fef9d7879eec3246", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fef9d7879eec3246", "to": "FIG-6a57c386160b5ead", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
